"""Verify unified Git diff blocks generated by autonomous coding agents."""
import re
from typing import List, Tuple

HUNK_RE = re.compile(r"^@@ -\d+(?:,\d+)? \+\d+(?:,\d+)? @@")

def validate_unified_diff(diff_text: str) -> Tuple[bool, List[str]]:
    issues: List[str] = []
    lines = diff_text.strip().splitlines()
    if not lines:
        return False, ["Empty diff block"]
    has_source = any(line.startswith("--- ") for line in lines)
    has_target = any(line.startswith("+++ ") for line in lines)
    has_hunk = any(HUNK_RE.match(line) for line in lines)
    if not has_source or not has_target:
        issues.append("Missing unified diff file headers ('---' and '+++')")
    if not has_hunk:
        issues.append("Missing valid unified hunk header")
    return len(issues) == 0, issues
